tasks.solution:
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.io.*;


public class Main {
    public static void main(String[] args) throws Exception {
        Path path = Path.of("quotes.txt");
        String message = "다음";
        // 기존 글을 남기는 저장 옵션이 필요해요.
        Files.writeString(path, message + "\n", StandardCharsets.UTF_8, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        System.out.println(Files.readString(path).strip());
    }
}
